import{_ as o,a0 as s,w as u,s as a,I as m,x as d,a1 as r,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"DNF 和 Yum 的区别，为什么 Yum 会被 DNF 取代？ | LCTT x X-CMD","titleTemplate":false,"description":"DNF 和 Yum 的区别，为什么 Yum 会被 DNF 取代？ | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"DNF 和 Yum 的区别，为什么 Yum 会被 DNF 取代？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"DNF 和 Yum 的区别，为什么 Yum 会被 DNF 取代？ | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20191220 The Difference Between DNF and YUM, Why is Yum Replaced by DNF","title":"DNF 和 Yum 的区别，为什么 Yum 会被 DNF 取代？","tag":"202004","desc":""},"relativePath":"202004/20191220 The Difference Between DNF and YUM, Why is Yum Replaced by DNF.md","filePath":"[post].md"}'),p={name:"202004/20191220 The Difference Between DNF and YUM, Why is Yum Replaced by DNF.md"};function i(f,t,D,Y,N,F){const e=s("Link");return u(),a("div",null,[t[20]||(t[20]=m("h1",{id:"dnf-和-yum-的区别-为什么-yum-会被-dnf-取代",tabindex:"-1"},[d("DNF 和 Yum 的区别，为什么 Yum 会被 DNF 取代？ "),m("a",{class:"header-anchor",href:"#dnf-和-yum-的区别-为什么-yum-会被-dnf-取代","aria-label":"Permalink to “DNF 和 Yum 的区别，为什么 Yum 会被 DNF 取代？”"},"​")],-1)),m("p",null,[t[2]||(t[2]=d("由于 Yum 中许多长期存在的问题仍未得到解决，因此 ",-1)),r(e,{href:"https://www.2daygeek.com/yum-command-examples-manage-packages-rhel-centos-systems/"},{default:n(()=>[...t[0]||(t[0]=[d("Yum 包管理器",-1)])]),_:1}),t[3]||(t[3]=d("已被 ",-1)),r(e,{href:"https://www.2daygeek.com/linux-dnf-command-examples-manage-packages-fedora-centos-rhel-systems/"},{default:n(()=>[...t[1]||(t[1]=[d("DNF 包管理器",-1)])]),_:1}),t[4]||(t[4]=d("取代。这些问题包括性能差、内存占用过多、依赖解析速度变慢等。",-1))]),t[21]||(t[21]=l('<p>DNF 使用 <code>libsolv</code> 进行依赖解析，由 SUSE 开发和维护，旨在提高性能。</p><p>Yum 主要是用 Python 编写的，它有自己的应对依赖解析的方法。它的 API 没有完整的文档，它的扩展系统只允许 Python 插件。</p><p>Yum 是 RPM 的前端工具，它管理依赖关系和资源库，然后使用 RPM 来安装、下载和删除包。</p><p>为什么他们要建立一个新的工具，而不是修复现有的问题呢？</p><p>Ales Kozamblak 解释说，这个修复在技术上是不可行的，而且 Yum 团队还没有准备好立即接受修改。</p><p>另外，最大的挑战是，Yum 有 56000 行代码，但 DNF 只有 29000 行代码。</p><p>所以除了分叉，没有办法解决。</p><p>不过 Yum 的运行情况还算可以。</p><div class="table-wrap"><table><thead><tr><th>编号</th><th>DNF（Dandified YUM）</th><th>YUM（Yellowdog Updater, Modified）</th></tr></thead><tbody><tr><td>1</td><td>DNF 使用 libsolv 来解析依赖关系，由 SUSE 开发和维护</td><td>YUM 使用公开的 API 来解析依赖关系</td></tr><tr><td>2</td><td>API 有完整的文档</td><td>API 没有完整的文档</td></tr><tr><td>3</td><td>由 C、C++、Python 编写的</td><td>只用 Python 编写</td></tr><tr><td>4</td><td>DNF 目前在 Fedora、RHEL 8、CentOS 8、OEL 8 和 Mageia 6/7 中使用</td><td>YUM 目前在 RHEL 6/7、CentOS 6/7、OEL 6/7 中使用</td></tr><tr><td>5</td><td>DNF 支持各种扩展</td><td>Yum 只支持基于 Python 的扩展</td></tr><tr><td>6</td><td>API 有良好的文档，因此很容易创建新的功能</td><td>因为 API 没有正确的文档化，所以创建新功能非常困难</td></tr><tr><td>7</td><td>DNF 在同步存储库的元数据时，使用的内存较少</td><td>在同步存储库的元数据时，YUM 使用了过多的内存</td></tr><tr><td>8</td><td>DNF 使用满足性算法来解决依赖关系解析（它是用字典的方法来存储和检索包和依赖信息）</td><td>由于使用公开 API 的原因，Yum 依赖性解析变得迟钝</td></tr><tr><td>9</td><td>从内存使用量和版本库元数据的依赖性解析来看，性能都不错</td><td>总的来说，在很多因素的影响下，表现不佳</td></tr><tr><td>10</td><td>DNF 更新：在 DNF 更新过程中，如果包中包含不相关的依赖，则不会更新</td><td>YUM 将在没有验证的情况下更新软件包</td></tr><tr><td>11</td><td>如果启用的存储库没有响应，DNF 将跳过它，并继续使用可用的存储库处理事务</td><td>如果有存储库不可用，YUM 会立即停止</td></tr><tr><td>12</td><td><code>dnf update</code> 和 <code>dnf upgrade</code> 是等价的</td><td>在 Yum 中则不同</td></tr><tr><td>13</td><td>安装包的依赖关系不更新</td><td>Yum 为这种行为提供了一个选项</td></tr><tr><td>14</td><td>清理删除的包：当删除一个包时，DNF 会自动删除任何没有被用户明确安装的依赖包</td><td>Yum 不会这样做</td></tr><tr><td>15</td><td>存储库缓存更新计划：默认情况下，系统启动后 10 分钟后，DNF 每小时会对配置的存储库检查一次更新。这个动作由系统定时器单元 <code>dnf-makecache.timer</code> 控制</td><td>Yum 也会这样做</td></tr><tr><td>16</td><td>内核包不受 DNF 保护。不像 Yum，你可以删除所有的内核包，包括运行中的内核包</td><td>Yum 不允许你删除运行中的内核</td></tr><tr><td>17</td><td>libsolv：用于解包和读取资源库。hawkey: 为 libsolv 提供简化的 C 和 Python API 库。librepo: 提供 C 和 Python（类似 libcURL）API 的库，用于下载 Linux 存储库元数据和软件包。libcomps: 是 yum.comps 库的替代品。它是用纯 C 语言编写的库，有 Python 2 和 Python 3 的绑定。</td><td>Yum 不使用单独的库来执行这些功能</td></tr><tr><td>18</td><td>DNF 包含 29000 行代码</td><td>Yum 包含 56000 行代码</td></tr><tr><td>19</td><td>DNF 由 Ales Kozumplik 开发</td><td>YUM 由 Zdenek Pavlas、Jan Silhan 和团队成员开发</td></tr></tbody></table></div><hr>',10)),m("p",null,[t[6]||(t[6]=d("via: ",-1)),r(e,{href:"https://www.2daygeek.com/comparison-difference-between-dnf-vs-yum/"},{default:n(()=>[...t[5]||(t[5]=[d("https://www.2daygeek.com/comparison-difference-between-dnf-vs-yum/",-1)])]),_:1})]),m("p",null,[t[11]||(t[11]=d("作者：",-1)),r(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:n(()=>[...t[7]||(t[7]=[d("Magesh Maruthamuthu",-1)])]),_:1}),t[12]||(t[12]=d(" 选题：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[8]||(t[8]=[d("lujun9972",-1)])]),_:1}),t[13]||(t[13]=d(" 译者：",-1)),r(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[d("wxy",-1)])]),_:1}),t[14]||(t[14]=d(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[10]||(t[10]=[d("wxy",-1)])]),_:1})]),m("p",null,[t[17]||(t[17]=d("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[15]||(t[15]=[d("LCTT",-1)])]),_:1}),t[18]||(t[18]=d(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:n(()=>[...t[16]||(t[16]=[d("Linux中国",-1)])]),_:1}),t[19]||(t[19]=d(" 荣誉推出",-1))])])}const T=o(p,[["render",i]]);export{P as __pageData,T as default};
